<script setup lang="ts">
import {TASK_CATEGORIES,type TaskCategory} from '#shared/types/tasks'
import type { ConsoleProfiles, DeviceActivity } from '#shared/types/consoles'
const props=defineProps<{ profiles:ConsoleProfiles; activity:DeviceActivity[]; visible:boolean; torrents:Array<{hash:string;name:string;state:string;progress:number}> }>()
const emit=defineEmits<{changed:[];torrent:[hash:string,action:'pause'|'resume'|'delete']}>()
const {t}=useAppLocale()
const query=ref(''),filter=ref('all'),onlyTasks=ref(false),message=ref(''),pending=ref(false)
const torrentCategories=ref<TaskCategory[]>([...TASK_CATEGORIES]),hiddenTorrents=ref<Record<string,string>>({})
const categoryLabels={active:'Активные',queued:'В очереди',completed:'Завершённые',failed:'Ошибки и пропуски'}
function torrentCategory(item:{state:string;progress:number}):TaskCategory {return /error|missingFiles|unknown/i.test(item.state)?'failed':item.progress>=1?'completed':/paused|stopped|queued/i.test(item.state)?'queued':'active'}
const visibleTorrents=computed(()=>props.torrents.filter(item=>hiddenTorrents.value[item.hash]!==`${item.state}:${item.progress}`))
const filteredTorrents=computed(()=>visibleTorrents.value.filter(item=>torrentCategories.value.includes(torrentCategory(item))).sort((a,b)=>Number(torrentCategory(b)==='active')-Number(torrentCategory(a)==='active')))
async function refreshTorrentsVisibility(){try{hiddenTorrents.value=(await $fetch<{hiddenTorrents:Record<string,string>}>('/api/consoles/torrent-tasks')).hiddenTorrents}catch{}}
async function clearTorrents(){try{await $fetch('/api/consoles/torrent-tasks',{method:'POST',body:{torrents:props.torrents}});await refreshTorrentsVisibility()}catch{message.value='Не удалось очистить историю загрузок'}}
function torrentDelete(hash:string){if(window.confirm(t('Убрать torrent-задание? Скачанные файлы останутся на диске.')))emit('torrent',hash,'delete')}
watch(()=>props.visible,value=>{if(value)void refreshTorrentsVisibility()});onMounted(refreshTorrentsVisibility)
const opened=reactive<Record<string,boolean>>({})
const activityFor=(id:string)=>props.activity.find(item=>item.consoleId===id)
const shown=computed(()=>props.profiles.consoles.filter(item=>(filter.value==='all'||filter.value===item.platform)&&`${item.name} ${item.ip}`.toLowerCase().includes(query.value.toLowerCase())&&(!onlyTasks.value||Object.values(activityFor(item.id)?.counts || {}).some(value=>value>0))).sort((a,b)=>score(b.id)-score(a.id)||a.name.localeCompare(b.name)))
function score(id:string){const counts=activityFor(id)?.counts;return counts?.active||activityFor(id)?.activePackageIds.length?2:counts?.queued?1:0}
function isOpen(id:string){return opened[id] ?? score(id)>0}
async function clearAll(){if(pending.value)return;pending.value=true;message.value='';const results=await Promise.allSettled(props.profiles.consoles.map(profile=>$fetch('/api/consoles/tasks',{method:'POST',body:{consoleId:profile.id,action:'clear'}})));const errors=results.filter(result=>result.status==='rejected').length;message.value=errors?`Не удалось очистить историю ${errors} устройств. Остальные списки очищены`:'Завершённые задания и ошибки убраны из всех списков';await clearTorrents();pending.value=false;emit('changed')}
async function cancelAll(id:string,resolve=false){const activity=activityFor(id);if(!activity?.queueId||pending.value)return;if(!resolve&&!window.confirm(t('Отменить очередь только этого устройства? Остальные приставки продолжат установку.')))return;pending.value=true;try{const result=await $fetch<{message?:string}>('/api/consoles/tasks',{method:'POST',body:{consoleId:id,queueId:activity.queueId,action:resolve?'resolve':'cancel'}});message.value=result.message || 'Очередь изменена';emit('changed')}catch(error:any){message.value=error?.data?.message||'Не удалось изменить очередь'}finally{pending.value=false}}
</script>
<template>
<section class="device-tasks"><header><div><h1>{{t('Задания')}}</h1><p>{{t('У каждой приставки своя очередь. Активные устройства всегда сверху.')}}</p></div><button :disabled="pending" @click="clearAll">{{t('Очистить завершённые и ошибки')}}</button></header><div class="filters"><input v-model="query" :placeholder="t('Найти устройство')"><select v-model="filter"><option value="all">{{t('Все')}}</option><option value="ps4">PS4</option><option value="ps5">PS5</option></select><label><input v-model="onlyTasks" type="checkbox"> {{t('Только с заданиями')}}</label></div><p v-if="message" class="pf-notice" role="status">{{t(message)}}</p>
<div class="devices-list"><article v-for="profile in shown" :key="profile.id" class="device-group"><button class="device-heading" :aria-expanded="isOpen(profile.id)" @click="opened[profile.id]=!isOpen(profile.id)"><span class="arrow">{{isOpen(profile.id)?'⌄':'›'}}</span><strong>{{profile.name}}</strong><span>{{profile.platform.toUpperCase()}} · {{profile.ip}}</span><small>{{t('Активные:')}} {{activityFor(profile.id)?.counts.active || 0}} · {{t('В очереди:')}} {{activityFor(profile.id)?.counts.queued || 0}} · {{t('Завершённые:')}} {{activityFor(profile.id)?.counts.completed || 0}} · {{t('Ошибки и пропуски:')}} {{activityFor(profile.id)?.counts.failed || 0}}</small><i :class="{online:profile.online}">●</i></button>
<div v-if="isOpen(profile.id)" class="device-details"><InstallationTasks :console-id="profile.id" :platform="profile.platform" :ip="profile.ip" :visible="visible" :torrents="[]" :queue-status="activityFor(profile.id)?.status || 'idle'" :cancelling="pending" @changed="emit('changed')" @stop="cancelAll(profile.id)" @resolve="cancelAll(profile.id,true)" /></div></article><p v-if="!shown.length" class="empty">{{t('Нет устройств в выбранном фильтре.')}}</p>
<section v-if="torrents.length" class="torrent-tasks"><header><h2>qBittorrent</h2><button @click="clearTorrents">{{t('Очистить')}}</button></header><div class="filters"><label v-for="category in TASK_CATEGORIES" :key="category"><input v-model="torrentCategories" type="checkbox" :value="category"> {{t(categoryLabels[category])}} {{visibleTorrents.filter(item=>torrentCategory(item)===category).length}}</label></div><article v-for="item in filteredTorrents" :key="item.hash"><strong>{{item.name}}</strong><span>{{Math.round(item.progress*100)}}% · {{item.state}}</span><button v-if="item.progress<1" @click="emit('torrent',item.hash,/paused|stopped/i.test(item.state)?'resume':'pause')">{{t(/paused|stopped/i.test(item.state)?'Продолжить':'Пауза')}}</button><button @click="torrentDelete(item.hash)">{{t('Убрать задачу')}}</button></article></section>
</div></section>
</template>
<style scoped>
.device-tasks{height:100%;min-height:0;display:flex;flex-direction:column;gap:14px}header,.filters{display:flex;align-items:center;gap:12px}header{justify-content:space-between}h1{margin:0;font-size:24px}p{margin:6px 0;color:#a39dad;font-size:12px}.filters>input{width:300px;max-width:45%}.filters label{font-size:12px}.devices-list{flex:1;min-height:0;overflow:auto;scrollbar-color:#8266c4 #19191c}.device-group{border:1px solid #39353f;background:#19191c;border-radius:10px;margin-bottom:12px;overflow:hidden}.device-heading{width:100%;display:flex;align-items:center;gap:14px;text-align:left;border:0;border-radius:0;padding:16px;background:#1e1d22}.device-heading strong{font-size:15px}.device-heading span:not(.arrow){color:#9994a5;font-size:11px}.device-heading small{margin-left:auto;color:#aba4b8;font-size:11px}.device-heading i{font-style:normal;color:#777}.device-heading .online{color:#8fd0a6}.arrow{color:#b89bdd;font-size:22px}.device-details{height:min(68vh,720px);min-height:300px;padding:16px;border-top:1px solid #39353f}.device-details :deep(.task-title h1){font-size:17px}.device-details :deep(.task-title p){display:none}.torrent-tasks{padding:12px}.torrent-tasks h2{font-size:17px}.torrent-tasks article{display:flex;gap:12px;align-items:center;padding:12px;border-bottom:1px solid #333139;font-size:12px}.torrent-tasks strong{flex:1}button,input:not([type=checkbox]),select{padding:9px 12px;background:#28272d;border:1px solid #454052;border-radius:8px;color:#e9e5ef;font-size:12px}button{cursor:pointer}button:disabled{opacity:.4}input{accent-color:#a786df}@media(max-width:900px){.device-heading{flex-wrap:wrap}.device-heading small{margin-left:0;width:100%}}
</style>
